from typing import List
from collections import Counter

def rankTeams(votes: List[str]) -> str:
    if not votes:
        return ""

    team_counts = {team: [0] * len(votes[0]) + [team] for team in votes[0]}

    for vote in votes:
        for i, team in enumerate(vote):
            team_counts[team][i] += 1

    sorted_teams = sorted(votes[0], key=lambda x: (-team_counts[x][:len(votes[0])], x))
    return ''.join(sorted_teams)

